<?php require "config.php";$codigo=trim($_GET["codigo"]??"");$s=$conexion->prepare("SELECT * FROM certificados WHERE codigo=? LIMIT 1");$s->bind_param("s",$codigo);$s->execute();$c=$s->get_result()->fetch_assoc();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verificación</title><style>body{font-family:Arial;background:#eee;padding:30px}.box{max-width:600px;margin:auto;background:#fff;padding:30px;border-radius:12px;text-align:center}.ok{color:green}.no{color:red}</style></head><body><div class="box"><?php if($c):?><h1 class="ok">✓ CERTIFICADO VÁLIDO</h1><p><b>Nombre:</b> <?=htmlspecialchars($c["nombre"]." ".$c["apellido"])?></p><p><b>Programa:</b> <?=htmlspecialchars($c["programa"])?></p><p><b>Fecha:</b> <?=$c["fecha_emision"]?></p><p><b>Código:</b> <?=htmlspecialchars($c["codigo"])?></p><p><b>Estado:</b> <?=$c["estado"]?></p><?php else:?><h1 class="no">✗ CERTIFICADO NO ENCONTRADO</h1><?php endif;?></div></body></html>